  "methodological_questions": [
    "How to reliably classify shapers as cut-heavy vs drive-heavy given low usage and rare play types?",
    "What performance metric best captures 'roles travel better' (minutes, net rating, travel forecast)?",
    "Is the sample of shaper movers large enough to detect a meaningful difference in portability?",
    "How to control for destination team context and play-type needs?",
    "Can cut-heavy classification be made stable with a minimum-possession threshold?",
    "Does the travel/fit framework already subsume cut vs drive effects?",
    "Are cut-heavy shapers fundamentally different in ways unrelated to travel (e.g., position, athleticism)?"
  ],
  "historical_evidence": [
    {
      "id": "FAM:SF-APPM-039",
      "status_as_recorded": "supported",
      "finding": "Travel forecast and fit quadrants predict mover outcomes (embedded minutes, net rating). LOO corr 0.1998, AUC 0.5986; additive > irrelevant in 98.4% of holdout splits."
    },
    {
      "id": "FAM:SF-PAP-033",
      "status_as_recorded": "supported",
      "finding": "Split-half validation of travel x fit ordering: additive > irrelevant on net rating in 96% of holdout splits; travel forecast correlates with destination net rating (median r 0.178)."
    },
    {
      "id": "FAM:SF-PAP-032",
      "status_as_recorded": "inconclusive",
      "finding": "Travel x fit quadrants show directional ordering in post-move minutes and net rating (additive > irrelevant), but correlations are weak (corr(delta, dest_net)=+0.077) and in-sample thresholds were used."
    },
    {
      "id": "FAM:SF-APPS-088",
      "status_as_recorded": "supported",
      "finding": "Connector absence displaces team offensive identity more than usage-matched non-organizer absence, demonstrating that structural roles have measurable team-level impact."
    },
    {
      "id": "FAM:SF-APPA-052",
      "status_as_recorded": "supported",
      "finding": "CUT-heavy games (CUT >15% of H2 mix) are extremely rare (4/272 games); the BEST-AVOID gap is not inflated by them, highlighting the low base rate of CUT-heavy contexts."
    },
    {
      "id": "FAM:SF32",
      "status_as_recorded": "artifact",
      "finding": "Rank-1 opener recommendations centered on CUT proved infeasible because CUT share targets exceeded actual team capacity by large margins (e.g., target 14-18% vs ceiling 2-6%)."
    }
  ],
  "failed_approaches": [
    {
      "id": "FAM:SF-PAP-032",
      "what_failed": "Direct prediction of individual mover outcomes from travel/fit quadrant",
      "why": "Inconclusive; weak correlations, in-sample thresholds, and possible lookahead/outcome-derived label risks limited the reliability of individual-level predictions."
    },
    {
      "id": "FAM:SF32",
      "what_failed": "Optimizing counter strategies on CUT play type without personnel constraints",
      "why": "Artifact: CUT targets were 3-10x real team ceilings, producing infeasible recommendations due to ignoring base rates and roster capacities."
    },
    {
      "id": "FAM:SF-APPS-086",
      "what_failed": "Using scalar structural load or displacement-weighted measures to predict connector ecosystem quality",
      "why": "Adequately powered null result; structural metrics added nothing beyond uniform average teammate lift."
    }
  ],
  "evidence_establishes": [
    "Travel (portability) and fit quadrants have predictive power for mover outcomes at an aggregate level.",
    "Additive-fit movers tend to outperform irrelevant-fit movers on embedded minutes and net rating.",
    "Structural roles (e.g., connector) produce measurable offensive-identity shifts when absent.",
    "CUT-heavy contexts are very rare in the NBA; CUT volume is naturally constrained."
  ],
  "evidence_does_not_establish": [
    "Whether cut-heavy shapers' roles travel better than drive-heavy shapers' roles.",
    "The relative portability of different play-type specializations within the shaper category.",
    "Whether the travel framework can differentiate subtypes of shapers reliably with current sample sizes.",
    "The stability and reliability of cut-heavy vs drive-heavy classification for low-usage players."
  ],
  "own_inferences": [
    "The question is a logical extension of the project's travel/fit research, but requires subclassifying shapers by their initiation-mix composition.",
    "With n=24 units, any comparison of cut-heavy vs drive-heavy shapers will have very low power, especially given the rarity of CUT initiations.",
    "Low-usage shapers by definition have few total initiations, making their play-type split estimates noisy and vulnerable to measurement error.",
    "If the travel forecast metric already captures play-type composition, a cut-vs-drive distinction may be partially redundant but could still reveal incremental information.",
    "A credible test would need multi-year data, strict minimum-possession thresholds, and careful out-of-sample validation, which likely requires more than the stated 24 units."
  ],
  "uncertainties": [
    "Precise operationalization of 'cut-heavy' and 'drive-heavy' (e.g., absolute share, relative to league average, continuous vs categorical).",
    "Whether the n=24 refers to shaper movers, team-seasons, or some other unit.",
    "Whether sufficient CUT and DRIVE initiations exist per shaper to produce stable classifications.",
    "Potential confound between play-type specialization and position, athletic traits, or team system."
  ],
