      {
        "code": "SAMPLE_SIZE_POWER",
        "text": "n=24 units severely limits power to detect a plausible effect size; even if the effect is large, confidence intervals will be wide."
      },
      {
        "code": "EXPOSURE_SPARSITY",
        "text": "CUT initiations are infrequent, especially for low-usage shapers, making cut-heavy classification unstable and possibly impossible for many players."
      },
      {
        "code": "MEASURE_RELIABILITY",
        "text": "Play-type shares in small initiation samples are noisy; shapers' cut/drive splits may not represent true stylistic tendencies."
      },
      {
        "code": "BASE_RATE",
        "text": "CUT-heavy profiles are rare in the league, so the number of true cut-heavy shaper movers could be near zero."
      }
    ]
  },
  "prior_work": {
    "already_answered": "no",
    "cited": [
      "FAM:SF-APPM-039",
      "FAM:SF-PAP-033",
      "FAM:SF-PAP-032",
      "FAM:SF-APPS-088",
      "FAM:SF-APPA-052",
      "FAM:SF32"
    ],
    "summary": "Earlier work validated travel/fit metrics for predicting mover outcomes and established the low base rate of CUT-heavy contexts, but did not examine whether cut-heavy shapers' roles are more portable than drive-heavy ones."
  },
  "risks": [
    {
      "code": "SAMPLE_SIZE_POWER",
      "text": "Only 24 units available; insufficient to detect a plausible difference between cut-heavy and drive-heavy shapers unless the effect is very large."
    },
    {
      "code": "EXPOSURE_SPARSITY",
      "text": "Low-usage shapers may have very few CUT or DRIVE initiations, leading to unreliable or missing classification."
    },
    {
      "code": "MEASURE_RELIABILITY",
      "text": "Play-type classification (especially distinguishing CUT from other off-ball actions) and small-sample split estimates introduce substantial noise."
    },
    {
      "code": "BASE_RATE",
      "text": "Cut-heavy shapers may be too rare to form a meaningful comparison group, as CUT is a low-frequency play type."
    },
    {
      "code": "CONFOUNDING",
      "text": "Cut-heavy and drive-heavy shapers may differ systematically in position, athleticism, or defensive role, which could confound travel success independent of play-type portability."
    },
    {
      "code": "OUTCOME_DERIVED_LABEL",
      "text": "If travel success is used to define cut-heavy vs drive-heavy post hoc, the comparison becomes circular."
    }
  ],
  "predicted_outcome": {
    "supported": 0.05,
    "rejected": 0.10,
    "untestable": 0.55,
    "artifact": 0.15,
    "uncertain": 0.15
  },
  "decision": "do_not_proceed",
  "design": {
    "estimand": "Average difference in post-move destination net rating (or embedded minutes) between shapers classified as cut-heavy and those classified as drive-heavy, where classification is based on pre-move share of CUT and DRIVE initiations exceeding a threshold (e.g., >40% of a player's total initiations) and meeting a minimum possession count (e.g., >=50 CUT+DRIVE initiations).",
    "unit": "Individual shaper mover (a player who changed teams between consecutive seasons and is classified as a Shaper in his pre-move season).",
    "sample": "All Shaper movers in the available data (2022-23 to 2025-26 seasons) who meet the possession threshold. Expected n ≈ 24.",
    "power": "With n=24 and an anticipated effect size of d ≈ 0.3-0.5, power is below 50% for a two-sided test at α=0.05. This design is underpowered; multi-year pooling or a Bayesian informative prior would be required to improve sensitivity.",
    "controls": "Destination team's offensive system (play-type needs, pace), pre-move usage rate, position, age, and overall team quality (net rating).",
    "falsification": "Check that pre-move cut/drive classification is stable under split-half resampling of the initiation record. Verify that cut-heavy shapers do not simply have higher total CUT volume because they play for CUT-heavy teams. Use a placebo test: compare travel success of shapers who are balanced (neither cut- nor drive-heavy) against the two extremes; a null result would weaken the hypothesis.",
    "multiplicity": "Pre-register a single primary outcome (destination net rating with a minimum floor of possessions) and a single contrast (cut-heavy > drive-heavy). Secondary analyses (minutes, travel forecast) will be reported as exploratory with correction.",
    "decision_rule": "One-sided test (cut-heavy shapers' median post-move net rating > drive-heavy) using a Mann-Whitney U test at α=0.05; also compute a Bayes factor with a half-normal prior (effect > 0). Conclude if Bayes factor > 3 and frequentist p < 0.05.",
    "data_version": "NBA per-game data as of 2026-08-08, including 2022-23 through 2025-26 regular seasons and playoffs."
  }
}}

